const results = $input.first().json.result;
const query      = $('Webhook').item.json.body.query;
const memoryCtx  = $('Webhook').item.json.body.memory_context || '';

let context = '';
const sources = [];

results.forEach((item, i) => {
  const { score, payload } = item;
  const {
    title, section_label, section_heading,
    text, source_url, doc_id, version_date
  } = payload;

  context += `\n\n--- Source ${i + 1} [${title} — ${section_label}] ---\n`;
  if (section_heading && section_heading !== section_label) {
    context += `Heading: ${section_heading}\n`;
  }
  context += text;

  sources.push({
    rank: i + 1,
    score: parseFloat(score.toFixed(4)),
    title,
    section_label,
    section_heading: section_heading || '',
    source_url: source_url || '',
    doc_id: doc_id || '',
    version_date: version_date || '',
    text_preview: text.substring(0, 300)
  });
});

return [{
  // Pass memory context forward for the LLM node
  json: {
    query,
    context: context.trim(),
    memory_context: memoryCtx,
    sources,
    retrieved_count: results.length,
    retrieved_at: new Date().toISOString()
  }
}];

