parameters.jsCode:
const ollama  = $input.first().json;
const ctx     = $('Format Context').first().json;

const answer = ollama.message?.content ?? 'No response generated.';
const doneAt = new Date().toISOString();

return [{
  json: {
    answer,
    sources: ctx.sources,
    trace: {
      query:           ctx.query,
      retrieved_count: ctx.retrieved_count,
      retrieved_at:    ctx.retrieved_at,
      generated_at:    doneAt,
      model:           ollama.model || 'llama3.1:8b',
      eval_count:      ollama.eval_count  || null,
      prompt_tokens:   ollama.prompt_eval_count || null
    },
    disclaimer: 'UNOFFICIAL consolidation. Authoritative text is the Government Gazette. Verify at SSO: https://sso.agc.gov.sg'
  }
}];
